function fireworks(){confetti();setTimeout(confetti,600);setTimeout(confetti,1200)}

// A self-contained, side-view adventure: jump over each habitat's animated obstacle.
const hazards=[230,430,635,800];
function rounded(x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function drawCloud(x,y,s){ctx.fillStyle='#ffffff88';ctx.beginPath();ctx.ellipse(x,y,s*1.35,s*.48,0,0,7);ctx.ellipse(x-s*.56,y+2,s*.64,s*.44,0,0,7);ctx.ellipse(x+s*.5,y-7,s*.62,s*.52,0,0,7);ctx.fill()}
function drawTree(x,y,s,color){ctx.fillStyle='#855e61';ctx.fillRect(x-s*.1,y-s*.65,s*.2,s*.7);ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y-s*.72,s*.43,0,7);ctx.arc(x-s*.28,y-s*.58,s*.3,0,7);ctx.arc(x+s*.27,y-s*.54,s*.32,0,7);ctx.fill()}
function drawBackground(w,h,t){const p=palettes[state.stage]||palettes[0];const grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,p[0]);grad.addColorStop(1,p[1]);ctx.fillStyle=grad;ctx.fillRect(0,0,w,h);
 // soft sun and drifting clouds
 ctx.globalAlpha=.6;ctx.fillStyle=p[3];ctx.beginPath();ctx.arc(w*.83,h*.2,Math.min(w,h)*.07,0,7);ctx.fill();ctx.globalAlpha=1;
 for(let i=0;i<5;i++){let x=((i*247-t*(.012+i*.001))%(w+180)+w+180)%(w+180)-70;drawCloud(x,h*(.17+(i%3)*.1),24+(i%2)*9)}
 // layered rolling hills
 ctx.fillStyle=p[2]+'66';ctx.beginPath();ctx.moveTo(0,h*.64);for(let x=0;x<=w+10;x+=10)ctx.lineTo(x,h*.56+Math.sin(x/w*7+state.stage)*h*.035);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();
 ctx.fillStyle='#ffffff20';for(let i=0;i<9;i++){const x=((i*151-t*.025)%(w+80)+w+80)%(w+80)-30;ctx.beginPath();ctx.arc(x,h*.60+(i%2)*h*.04,3+(i%3),0,7);ctx.fill()}
}
function drawGround(w,h,t){const p=palettes[state.stage];const y=h*.79;ctx.fillStyle=p[2];ctx.fillRect(0,y,w,h-y);ctx.fillStyle='#ffffff39';ctx.fillRect(0,y,w,8);ctx.fillStyle='#28395722';for(let i=0;i<18;i++){let x=((i*83-t*.11)%(w+30)+w+30)%(w+30);ctx.beginPath();ctx.ellipse(x,y+30+(i%3)*21,17,3,0,0,7);ctx.fill()}
 // floating stepping stones and distant habitat decorations
 for(let i=0;i<5;i++){const x=(i*235+90-t*.04)%(w+100);ctx.globalAlpha=.55;rounded(x,y-38-(i%2)*15,65,11,6,'#ffffffaa');ctx.globalAlpha=1}
 for(let i=0;i<8;i++){const x=((i*157-t*.035)%(w+80)+w+80)%(w+80)-20;const sy=y-20-(i%3)*10;ctx.fillStyle=p[3]+'bb';ctx.beginPath();ctx.arc(x,sy,3+(i%2)*2,0,7);ctx.fill()}
}
function drawHazard(x,y,type,t,scale){const bob=Math.sin(t*.004+x)*4*scale;ctx.save();ctx.translate(x,y+bob);ctx.scale(scale,scale);ctx.shadowColor='#18284a30';ctx.shadowBlur=9;ctx.shadowOffsetY=5;
 switch(type){case'stump':rounded(-18,-31,36,32,8,'#a96f4a');ctx.fillStyle='#d9a06a';ctx.beginPath();ctx.ellipse(0,-30,18,6,0,0,7);ctx.fill();break;
 case'log':ctx.translate(0,-18);ctx.rotate(Math.sin(t*.002)*.07);rounded(-35,-12,70,24,12,'#946041');ctx.fillStyle='#d3a16b';ctx.beginPath();ctx.ellipse(-31,0,6,12,0,0,7);ctx.fill();break;
 case'crystal':ctx.fillStyle='#7b62dc';ctx.beginPath();ctx.moveTo(-20,0);ctx.lineTo(-14,-42);ctx.lineTo(-2,-24);ctx.lineTo(6,-51);ctx.lineTo(22,0);ctx.closePath();ctx.fill();ctx.fillStyle='#c9a9ff';ctx.beginPath();ctx.moveTo(-14,-40);ctx.lineTo(-2,-24);ctx.lineTo(-14,-12);ctx.closePath();ctx.fill();break;
 case'wave':ctx.fillStyle='#409ec3';ctx.beginPath();ctx.ellipse(0,-9,34,13,Math.sin(t*.003)*.2,0,7);ctx.fill();ctx.fillStyle='#d5ffff';ctx.beginPath();ctx.ellipse(6,-14,17,5,0,0,7);ctx.fill();break;
 case'rock':ctx.fillStyle='#7687b3';ctx.beginPath();ctx.moveTo(-25,0);ctx.lineTo(-19,-29);ctx.lineTo(-4,-38);ctx.lineTo(21,-26);ctx.lineTo(27,0);ctx.fill();break;
 case'lava':ctx.fillStyle='#e65d43';ctx.beginPath();ctx.ellipse(0,-8,32,11,0,0,7);ctx.fill();ctx.fillStyle='#ffdc68';ctx.beginPath();ctx.arc(-9,-12,5,0,7);ctx.arc(13,-6,4,0,7);ctx.fill();break;
 case'ice':ctx.fillStyle='#a5eaff';ctx.beginPath();ctx.moveTo(-23,0);ctx.lineTo(-13,-34);ctx.lineTo(0,-15);ctx.lineTo(13,-43);ctx.lineTo(26,0);ctx.fill();break;
 case'pillar':case'gear':rounded(-15,-42,30,43,5,type==='gear'?'#dca95e':'#c79473');ctx.fillStyle='#fff4c4';ctx.fillRect(-8,-33,4,26);if(type==='gear'){ctx.strokeStyle='#ffdb75';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,-44,17,0,7);ctx.stroke()}break;
 case'cloud':ctx.fillStyle='#897ce0';ctx.beginPath();ctx.ellipse(0,-12,30,12,0,0,7);ctx.arc(-12,-19,10,0,7);ctx.arc(9,-21,12,0,7);ctx.fill();break;
 case'thorn':ctx.fillStyle='#597655';ctx.beginPath();ctx.moveTo(-27,0);ctx.lineTo(-11,-28);ctx.lineTo(-3,-8);ctx.lineTo(13,-35);ctx.lineTo(26,0);ctx.fill();break;
 case'water':ctx.fillStyle='#55bde0';ctx.beginPath();ctx.ellipse(0,-10,31,11,Math.sin(t*.002)*.3,0,7);ctx.fill();ctx.fillStyle='#d8ffff';ctx.fillRect(-18,-14,21,3);break;
 case'flask':ctx.fillStyle='#d8e9ff';ctx.beginPath();ctx.moveTo(-9,-39);ctx.lineTo(9,-39);ctx.lineTo(7,-20);ctx.lineTo(20,0);ctx.lineTo(-20,0);ctx.lineTo(-7,-20);ctx.closePath();ctx.fill();ctx.fillStyle='#8c73e6';ctx.fillRect(-13,-11,26,8);break;
 case'cactus':rounded(-9,-36,18,37,8,'#5caf76');rounded(-22,-25,12,9,5,'#5caf76');ctx.fillRect(-22,-25,6,15);rounded(10,-20,12,9,5,'#5caf76');ctx.fillRect(16,-20,6,13);break;
 case'star':ctx.fillStyle='#ffe57b';ctx.beginPath();for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,r=i%2?10:21;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r-22)}ctx.closePath();ctx.fill();break;
 }
 ctx.restore()}
function drawPip(x,y,scale,t){ctx.save();ctx.translate(x,y+Math.sin(t*.008)*2);ctx.scale(scale,scale);ctx.shadowColor='#24324c40';ctx.shadowBlur=12;ctx.shadowOffsetY=5;ctx.fillStyle=state.invuln>0&&Math.floor(t/90)%2?'#ffffff99':'#50d7c6';ctx.beginPath();ctx.ellipse(0,-21,19,23,Math.sin(t*.003)*.08,0,7);ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;
 // little flagella and backpack
 ctx.strokeStyle='#24b99f';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-16,-20);ctx.quadraticCurveTo(-31,-22,-29,-7);ctx.stroke();ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(-6,-25,4,6,0,0,7);ctx.ellipse(7,-25,4,6,0,0,7);ctx.fill();ctx.fillStyle='#263552';ctx.beginPath();ctx.arc(-5,-24,1.8,0,7);ctx.arc(8,-24,1.8,0,7);ctx.fill();ctx.strokeStyle='#263552';ctx.lineWidth=2;ctx.beginPath();ctx.arc(1,-17,5,.2,2.9);ctx.stroke();ctx.fillStyle='#ffcf6a';ctx.beginPath();ctx.arc(0,-46,5,0,7);ctx.fill();ctx.restore()}
function draw(w,h,t){ctx.clearRect(0,0,w,h);drawBackground(w,h,t);drawGround(w,h,t);const sx=w/960,sy=h/700,ground=h*.79;const stage=checkpoints[state.stage]||checkpoints[14];
 // stage label in scene
 ctx.fillStyle='#ffffffb8';ctx.font=`800 ${Math.max(11,13*sx)}px DM Sans, sans-serif`;ctx.textAlign='left';ctx.fillText(`${stage.place}  ✦`,20, h*.145);
 // decorative plants / structures vary by habitat
 for(let i=0;i<5;i++){const px=((i*240+35-t*.018)%(w+80)+w+80)%(w+80);if(state.stage===0||state.stage===9){drawTree(px,ground-3,35+(i%2)*10,palettes[state.stage][2]+'bb')}else if(state.stage===7||state.stage===13){ctx.fillStyle=palettes[state.stage][2]+'77';rounded(px,ground-110,24,110,5,ctx.fillStyle);ctx.fillStyle='#ffffff44';ctx.fillRect(px+6,ground-100,4,80)}else if(state.stage===8){ctx.globalAlpha=.55;drawCloud(px,ground-85,33);ctx.globalAlpha=1}else{ctx.globalAlpha=.55;ctx.fillStyle=palettes[state.stage][3];ctx.beginPath();ctx.arc(px,ground-35-(i%3)*15,8,0,7);ctx.fill();ctx.globalAlpha=1}}
 // checkpoint beacon at the end
 const endx=930*sx;ctx.globalAlpha=.25+.15*Math.sin(t*.006);ctx.fillStyle='#fff6a4';ctx.beginPath();ctx.ellipse(endx,ground-42*sy,37*sx,50*sy,0,0,7);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#fff8c4';ctx.lineWidth=3;ctx.beginPath();ctx.arc(endx,ground-46*sy,27*sx,0,7);ctx.stroke();ctx.fillStyle='#ffe478';ctx.font=`${30*sx}px serif`;ctx.textAlign='center';ctx.fillText('✦',endx,ground-37*sy);
 hazards.forEach((hx,i)=>drawHazard(hx*sx,ground,stage.hazard,t+(i*450),sx));
 state.coins.forEach(c=>{if(c.got)return;const cx=c.x*sx,cy=ground-61*sy+Math.sin(t*.005+c.phase)*6*sy;ctx.save();ctx.shadowColor='#ffd34d';ctx.shadowBlur=15;ctx.fillStyle='#ffd56d';ctx.beginPath();ctx.ellipse(cx,cy,9*sx,12*sy,Math.sin(t*.004+c.phase)*.3,0,7);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff6c2';ctx.font=`bold ${10*sx}px sans-serif`;ctx.textAlign='center';ctx.fillText('✦',cx,cy+4*sy);ctx.restore()});
 const px=state.x*sx,py=ground-(state.y*sy);drawPip(px,py,sx,t);
 // subtle obstacle hints
 ctx.fillStyle='#ffffffaa';ctx.font=`700 ${11*sx}px DM Sans, sans-serif`;ctx.textAlign='center';ctx.fillText('JUMP!',hazards[Math.floor(t/3600)%hazards.length]*sx,ground-76*sy);
}
function update(dt,t){if(state.screen!=='')return;const left=state.keys.a||state.keys.arrowleft||state.keys.s||state.keys.arrowdown;const right=state.keys.d||state.keys.arrowright||state.keys.w||state.keys.arrowup;const speed=240;if(left)state.x-=speed*dt;if(right)state.x+=speed*dt;state.x=Math.max(24,Math.min(960,state.x));if(state.jumping){state.vy+=1450*dt;state.y+=state.vy*dt;if(state.y<=0){state.y=0;state.vy=0;state.jumping=false}}
 const scale=canvas.clientWidth/960;state.invuln=Math.max(0,state.invuln-dt);if(state.invuln<=0){for(const hx of hazards){if(Math.abs(state.x-hx)<38&&state.y<38){state.x=Math.max(45,hx-68);state.invuln=1.1;setToast('Boing! Time your jump over the obstacle!');break}}}
 for(const c of state.coins){if(!c.got&&Math.abs(state.x-c.x)<23&&state.y<90){c.got=true;setToast('Sparkle collected! ✨')}}
 if(state.x>=905){state.x=905;question()}
}
function loop(t){raf=requestAnimationFrame(loop);const dt=Math.min(.033,(t-last)/1000||0);last=t;update(dt,t);draw(canvas.clientWidth,canvas.clientHeight,t)}
raf=requestAnimationFrame(loop);
</script>
</body>
</html>

